A prompt registry can be as simple as a small class that stores each version's text alongside its status and evaluation score, and exposes the current production version by lookup rather than by hardcoding a prompt string somewhere in application code:

```python
from dataclasses import dataclass, field
from datetime import datetime


@dataclass
class PromptVersion:
    prompt_id: str
    version: int
    text: str
    status: str = "testing"          # "testing" | "production" | "retired"
    eval_score: float | None = None
    deployed_at: datetime | None = None


class PromptRegistry:
    def __init__(self):
        self._versions: dict[str, list[PromptVersion]] = {}

    def register_version(self, prompt_id: str, text: str) -> PromptVersion:
        history = self._versions.setdefault(prompt_id, [])
        pv = PromptVersion(prompt_id, version=len(history) + 1, text=text)
        history.append(pv)
        return pv

    def record_eval(self, prompt_id: str, version: int, score: float) -> None:
        self._get(prompt_id, version).eval_score = score

    def promote_to_production(self, prompt_id: str, version: int) -> None:
        for pv in self._versions[prompt_id]:
            if pv.status == "production":
                pv.status = "retired"
        target = self._get(prompt_id, version)
        target.status = "production"
        target.deployed_at = datetime.utcnow()

    def get_production_prompt(self, prompt_id: str) -> str:
        for pv in self._versions[prompt_id]:
            if pv.status == "production":
                return pv.text
        raise LookupError(f"no production version for {prompt_id}")

    def _get(self, prompt_id: str, version: int) -> PromptVersion:
        return next(v for v in self._versions[prompt_id] if v.version == version)
```

Every version is retained rather than overwritten, `record_eval` links a version to its evaluation results the way the lesson describes, and `get_production_prompt` gives application code a single source of truth instead of a prompt string embedded directly in a request handler.
